    def alignment_score(sign):
        groups = {}
        for r, c, value in clues:
            k = c - r if sign == 1 else c + r
            groups.setdefault((value, k), 0)
            groups[(value, k)] += 1
        return sum(n * (n - 1) // 2 for n in groups.values())

    sign = 1 if alignment_score(1) >= alignment_score(-1) else -1
    observed = {}
    for r, c, value in clues:
        k = c - r if sign == 1 else c + r
        if k in observed and observed[k] != value:
